// Build an ordered brand index: full names + first-word aliases, longest first
const BRAND_INDEX = (() => {
  const out = [];
  for (const [name, dbKey] of Object.entries(NOVA_DB.brand_to_db)) {
    const n = name.toLowerCase();
    out.push({ pat: n, dbKey });
    const fw = n.split(/\s+/)[0];
    if (fw !== n && fw.length >= 4) out.push({ pat: fw, dbKey });
  }
  out.sort((a, b) => b.pat.length - a.pat.length);
  return out;
})();

function escapeRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

function detectBrand(text) {
  const t = text.toLowerCase();
  for (const { pat, dbKey } of BRAND_INDEX) {
    const re = new RegExp('\\b' + escapeRe(pat) + '\\b');
    if (re.test(t)) return dbKey;
  }
  return null;
}

function detectCodes(text) {
  const codes = new Set();
  const re = /\b([A-Za-z][0-9]{1,3}|U[0-9]+|H[0-9]+|EE|BF|AL)\b/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    const c = m[1].toUpperCase();
    if (c.length <= 5) codes.add(c);
  }
  const re2 = /\bcode\s+([0-9]{1,3})\b/gi;
  while ((m = re2.exec(text)) !== null) codes.add(m[1]);
  // Also flash-count style: "flashing 3 times"
  const re3 = /flash(?:ing|es)?\s+(\d{1,2})\s+times?/i;
  m = re3.exec(text);
  if (m) codes.add(m[1]);
  return Array.from(codes);
}

function lookupCode(dbKey, code) {
  const brand = NOVA_DB.brands[dbKey];
  if (!brand) return null;
  const up = String(code).toUpperCase();
  return brand.codes.find(c => String(c.code).toUpperCase() === up) || null;
}

function buildGroundingBlock(userMessage) {
  const dbKey = detectBrand(userMessage);
  if (!dbKey) return '';
  const codes = detectCodes(userMessage);
  if (!codes.length) return '';
  for (const c of codes) {
    const hit = lookupCode(dbKey, c);
    if (!hit) continue;
    let b = `KNOWN_CODE_DATA (authoritative — NovaCTRL master database):\n`;
    b += `Brand database: ${dbKey}\n`;
    b += `Code: ${hit.code}\n`;
    b += `Meaning: ${hit.meaning}\n`;
    if (hit.series && hit.series.length) b += `Series applicable: ${hit.series.join(', ')}\n`;
    if (hit.causes && hit.causes.length) b += `Likely causes:\n- ${hit.causes.join('\n- ')}\n`;
    if (hit.steps && hit.steps.length) b += `Diagnostic steps:\n${hit.steps.join('\n')}\n`;
    if (hit.action) b += `Action required: ${hit.action}\n`;
    if (hit.accuracy) b += `Accuracy note: ${hit.accuracy}\n`;
    if (hit.safety) b += `SAFETY FLAG: true — lead your response with a bold safety alert.\n`;
    return b;
  }
  return '';
}

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type',
  'Access-Control-Max-Age': '86400',
};

export default {
  async fetch(request, env) {
    if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: CORS });
    if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405);

    let body;
    try { body = await request.json(); } catch { return json({ error: 'Invalid JSON' }, 400); }

    const incoming = Array.isArray(body.messages) ? body.messages : [];
    if (!incoming.length) return json({ error: 'No messages' }, 400);

    const trimmed = incoming.slice(-12).map(m => ({
      role: m.role === 'user' ? 'user' : 'assistant',
      content: String(m.content || '').slice(0, 2000),
    }));

    const lastUser = [...trimmed].reverse().find(m => m.role === 'user');
    const grounding = lastUser ? buildGroundingBlock(lastUser.content) : '';

    const systemContent = grounding
      ? `${grounding}\n\n---\n\n${NOVA_CLAW_SYSTEM_PROMPT}`
      : NOVA_CLAW_SYSTEM_PROMPT;

    const messages = [{ role: 'system', content: systemContent }, ...trimmed];

    try {
      const result = await env.AI.run('@cf/meta/llama-3.1-8b-instruct', {
        messages, max_tokens: 512, temperature: 0.3,
      });
      const reply = (result && (result.response || result.output)) || 'No response.';
      return json({ reply, grounded: !!grounding });
    } catch (err) {
      return json({ error: 'Worker AI error', detail: String(err) }, 500);
    }
  },
};

function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), {
    status: status,
    headers: { ...CORS, 'Content-Type': 'application/json' },
  });
}
